import sys

def set_zero_brute(m):
    if not m: return m
    rows, cols = len(m), len(m[0])
    zero_rows = [False] * rows
    zero_cols = [False] * cols
    for i in range(rows):
        for j in range(cols):
            if m[i][j] == 0:
                zero_rows[i] = True
                zero_cols[j] = True
    for i in range(rows):
        for j in range(cols):
            if zero_rows[i] or zero_cols[j]:
                m[i][j] = 0
    return m

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    matrix = []
    idx = 2
    for _ in range(m):
        matrix.append([int(x) for x in data[idx:idx + n]])
        idx += n
    set_zero_brute(matrix)
    for row in matrix:
        print(' '.join(map(str, row)))

import sys

def set_zero_opt(m):
    if not m: return m
    rows, cols = len(m), len(m[0])
    row0 = any(m[0][j] == 0 for j in range(cols))
    col0 = any(m[i][0] == 0 for i in range(rows))
    for i in range(1, rows):
        for j in range(1, cols):
            if m[i][j] == 0:
                m[0][j] = 0
                m[i][0] = 0
    for i in range(1, rows):
        for j in range(1, cols):
            if m[i][0] == 0 or m[0][j] == 0:
                m[i][j] = 0
    if row0:
        for j in range(cols):
            m[0][j] = 0
    if col0:
        for i in range(rows):
            m[i][0] = 0
    return m

